referenceSolutions.javascript:
export function searchRotatedArray(values, target) {
  let low = 0, high = values.length - 1;
  while (low <= high) {
    const middle = Math.floor((low + high) / 2);
    if (values[middle] === target) return middle;
    if (values[low] <= values[middle]) {
      if (values[low] <= target && target < values[middle]) high = middle - 1;
      else low = middle + 1;
    } else {
      if (values[middle] < target && target <= values[high]) low = middle + 1;
      else high = middle - 1;
    }
  }
  return -1;
}

